+import java.util.stream.Stream;
+
+/**
+ * UC-002: View Veterinarians.
+ *
+ * Lists every veterinarian with first name, last name and a comma-separated
+ * list of specialties ("none" if the vet holds none). The grid loads lazily
+ * from {@link VetRepository} as the visitor scrolls (BR-001).
+ */
+@Route(value = "vets", layout = MainLayout.class)
+@PageTitle("Veterinarians")
+public class VetListView extends VerticalLayout {
+
+    private final transient VetRepository vetRepository;
+
+    public VetListView(VetRepository vetRepository) {
+        this.vetRepository = vetRepository;
+        setSizeFull();
+
+        H2 heading = new H2("Veterinarians");
+        heading.addClassNames(LumoUtility.Margin.NONE);
+
+        Grid<Vet> grid = new Grid<>();
+        grid.addColumn(Vet::firstName).setHeader("First Name").setSortable(false);
+        grid.addColumn(Vet::lastName).setHeader("Last Name").setSortable(false);
+        grid.addColumn(VetListView::specialties).setHeader("Specialties").setSortable(false);
+        grid.setItems(
+                query -> findPage(query.getOffset(), query.getLimit()),
+                query -> count());
+        grid.setSizeFull();
+
+        add(heading, grid);
+    }
+
+    private Stream<Vet> findPage(int offset, int limit) {
+        return vetRepository.findPage(offset, limit);
+    }
+
+    private int count() {
+        return vetRepository.count();
+    }
+
+    private static String specialties(Vet vet) {
+        if (vet.specialties().isEmpty()) {
+            return "none";
+        }
+        return vet.specialties().stream()
+                .map(Specialty::name)
+                .collect(Collectors.joining(", "));
+    }
+}
