+import org.jooq.DSLContext;
+import org.junit.jupiter.api.Test;
+import org.springframework.beans.factory.annotation.Autowired;
+
+import java.util.List;
+
+import static ai.unifiedprocess.demo.petclinic.database.Tables.VETS;
+import static ai.unifiedprocess.demo.petclinic.database.Tables.VET_SPECIALTIES;
+import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+
+/**
+ * UC-002: View Veterinarians.
+ */
+class UC002ViewVeterinariansTest extends PetClinicTestBase {
+
+    private static final int COL_FIRST_NAME = 0;
+    private static final int COL_LAST_NAME = 1;
+    private static final int COL_SPECIALTIES = 2;
+
+    @Autowired
+    private DSLContext dsl;
+
+    @Autowired
+    private VetRepository vetRepository;
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-003")
+    void veterinariansLinkOpensTheDirectory() {
+        // No authentication is performed, covering BR-003 (Anonymous Access).
+        navigate(VetListView.class);
+        SideNavItem vetsLink = assertDoesNotThrow(() -> find(SideNavItem.class)
+                        .withPropertyValue(SideNavItem::getLabel, "Veterinarians").single(),
+                "Expected a Veterinarians item in the " + MainLayout.NAV_LABEL);
+
+        assertEquals("vets", vetsLink.getPath());
+        assertEquals("vets", UI.getCurrent().getInternals().getActiveViewLocation().getPath());
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
+    void gridShowsEveryVetWithNamesAndSpecialties() {
+        navigate(VetListView.class);
+        GridTester<Grid<Vet>, Vet> grid = vetGrid();
+
+        assertEquals("First Name", grid.getHeaderCell(COL_FIRST_NAME));
+        assertEquals("Last Name", grid.getHeaderCell(COL_LAST_NAME));
+        assertEquals("Specialties", grid.getHeaderCell(COL_SPECIALTIES));
+        assertEquals(6, grid.size());
+
+        // Seed vet Helen Leary holds radiology only.
+        int leary = rowOf(grid, "Leary");
+        assertEquals("Helen", grid.getCellText(leary, COL_FIRST_NAME));
+        assertEquals("radiology", grid.getCellText(leary, COL_SPECIALTIES));
+    }
+
+    @Test
+    @UseCase(id = "UC-002")
+    void vetWithoutSpecialtiesShowsNone() {
+        navigate(VetListView.class);
+        GridTester<Grid<Vet>, Vet> grid = vetGrid();
+
+        // Seed vet James Carter holds no specialty.
+        assertEquals("none", grid.getCellText(rowOf(grid, "Carter"), COL_SPECIALTIES));
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-002")
+    void specialtiesAreListedAlphabetically() {
+        navigate(VetListView.class);
+        GridTester<Grid<Vet>, Vet> grid = vetGrid();
+
+        // Linda Douglas was assigned surgery before dentistry in the seed data.
+        assertEquals("dentistry, surgery", grid.getCellText(rowOf(grid, "Douglas"), COL_SPECIALTIES));
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-001")
+    void gridLoadsVetsLazilyInChunks() {
+        navigate(VetListView.class);
+        Grid<?> grid = find(Grid.class).single();
+        assertFalse(grid.getDataProvider().isInMemory(),
+                "Expected the vet grid to fetch rows from the backend, not hold them in memory");
+
+        List<String> page = vetRepository.findPage(2, 2).map(Vet::lastName).toList();
+        assertEquals(List.of("Jenkins", "Leary"), page,
+                "Expected the third and fourth vet by last name as one chunk");
+        assertEquals(6, vetRepository.count());
+    }
+
+    @Test
+    @UseCase(id = "UC-002", scenario = "A1: No Veterinarians Registered")
+    void emptyClinicRendersGridWithoutRows() {
+        dsl.deleteFrom(VET_SPECIALTIES).execute();
+        dsl.deleteFrom(VETS).execute();
+
+        navigate(VetListView.class);
+
+        assertEquals(0, vetGrid().size());
+    }
+
+    @SuppressWarnings("unchecked")
+    private GridTester<Grid<Vet>, Vet> vetGrid() {
+        Grid<Vet> grid = assertDoesNotThrow(() -> (Grid<Vet>) find(Grid.class).single(),
+                "Expected exactly one veterinarians grid");
+        return test(grid);
+    }
+
+    private static int rowOf(GridTester<Grid<Vet>, Vet> grid, String lastName) {
+        for (int row = 0; row < grid.size(); row++) {
+            if (lastName.equals(grid.getCellText(row, COL_LAST_NAME))) {
+                return row;
+            }
+        }
+        throw new AssertionError("No vet with last name " + lastName + " in the grid");
+    }
+}
